def hidden_rule_fn(state):
    # Extract particles by type
    sponts = [p for p in state if p['type'] == 'SPONT']
    vrixs = [p for p in state if p['type'] == 'VRIX']
    krauls = [p for p in state if p['type'] == 'KRAUL']

    def wrap_dist(dx_raw, dy_raw):
        dx = dx_raw % 8
        if dx > 4:
            dx -= 8
        dy = dy_raw % 8
        if dy > 4:
            dy -= 8
        return dx, dy

    def grolp_dist(p1, p2):
        dx, dy = wrap_dist(p2['x'] - p1['x'], p2['y'] - p1['y'])
        if p1['type'] == p2['type']:
            return abs(dx) * abs(dy) + 1
        else:
            return abs(dx) + 2 * abs(dy)

    def find_nearest_diff(p, candidates):
        best = None
        best_dist = float('inf')
        for c in candidates:
            d = grolp_dist(p, c)
            if d < best_dist:
                best_dist = d
                best = c
        return best

    result = []
    for p in state:
        x, y = p['x'], p['y']
        if p['type'] == 'SPONT':
            if krauls:
                target = find_nearest_diff(p, krauls)
                dx, dy = wrap_dist(target['x'] - x, target['y'] - y)
                # Move AWAY from target in y-direction only
                sign_dy = 1 if dy > 0 else (-1 if dy < 0 else 0)
                new_y = (y - sign_dy) % 8
                new_x = x
            else:
                new_x, new_y = x, y
        elif p['type'] == 'VRIX':
            if sponts:
                target = find_nearest_diff(p, sponts)
                dx, dy = wrap_dist(target['x'] - x, target['y'] - y)
                # Move TOWARD target in both x and y
                sign_dx = 1 if dx > 0 else (-1 if dx < 0 else 0)
                sign_dy = 1 if dy > 0 else (-1 if dy < 0 else 0)
                new_x = (x + sign_dx) % 8
                new_y = (y + sign_dy) % 8
            else:
                new_x, new_y = x, y
        elif p['type'] == 'KRAUL':
            if vrixs:
                target = find_nearest_diff(p, vrixs)
                dx, dy = wrap_dist(target['x'] - x, target['y'] - y)
                # Move TOWARD target in both x and y
                sign_dx = 1 if dx > 0 else (-1 if dx < 0 else 0)
                sign_dy = 1 if dy > 0 else (-1 if dy < 0 else 0)
                new_x = (x + sign_dx) % 8
                new_y = (y + sign_dy) % 8
            else:
                new_x, new_y = x, y
        else:
            new_x, new_y = x, y
        result.append({'type': p['type'], 'x': new_x, 'y': new_y})

    return result
